import{_ as e,o as d,c as a,a4 as s}from"./chunks/framework.B8PHay3u.js";const k=JSON.parse('{"title":"部署指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1789823569000}'),i={name:"guide.md"};function o(c,t,r,h,n,l){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="部署指南" tabindex="-1">部署指南 <a class="header-anchor" href="#部署指南" aria-label="Permalink to &quot;部署指南&quot;">​</a></h1><h2 id="组成" tabindex="-1">组成 <a class="header-anchor" href="#组成" aria-label="Permalink to &quot;组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>目录</th><th>发布方式</th></tr></thead><tbody><tr><td>服务端（FastAPI）</td><td><code>server/</code></td><td>镜像 <code>electrical-manager:server</code></td></tr><tr><td>网页端（Vue 3 + nginx）</td><td><code>web/</code></td><td>镜像 <code>electrical-manager:web</code></td></tr><tr><td>小程序</td><td><code>miniprogram/</code></td><td>CI 上传微信小程序代码</td></tr><tr><td>数据库结构与种子数据</td><td><code>docs/references/database/init.sql</code></td><td>手工初始化</td></tr><tr><td>项目站点（本站）</td><td><code>docs/websites/</code></td><td>CI 构建后发布到 <code>gh-pages</code> 分支</td></tr><tr><td>接口文档 / Mock</td><td><code>docs/openapi.yaml</code></td><td>CI 同步到 Apifox</td></tr></tbody></table><p>接口文档与 Mock 由 CI 从 <code>docs/openapi.yaml</code> 同步到 Apifox，在线查看见<a href="/Electrical-Manager/api">接口文档</a>。</p><h2 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to &quot;Docker 部署&quot;">​</a></h2><p>前提：外部 MySQL 8.0+（库先建好）与外部网络 <code>1panel-network</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Sakana-1314/Electrical-Manager.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Electrical-Manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/env/.env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 按注释填写</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">databas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/references/database/init.sql</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p><code>docker-compose.yml</code> 使用 <code>ghcr.io/sakana-1314/electrical-manager:server</code> 与 <code>:web</code> 两个镜像；端口由 <code>BACKEND_PORT</code>（默认 8000）和 <code>FRONTEND_PORT</code>（默认 8080）控制。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>至少设置 <code>APP_DATABASE_URL</code> 与 <code>APP_JWT_SECRET</code>，其余按需：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>APP_DATABASE_URL</code></td><td>如 <code>mysql+asyncmy://user:pass@mysql:3306/db?charset=utf8mb4</code>，密码需 URL 编码。</td></tr><tr><td><code>APP_JWT_SECRET</code></td><td>至少 32 位随机字符串，生产环境必须修改。</td></tr><tr><td><code>APP_ACCESS_TOKEN_MINUTES</code></td><td>登录有效期（分钟），默认 480。</td></tr><tr><td><code>APP_FERNET_KEY</code></td><td>可选，加密 API Key / Webhook 密钥的专用密钥；留空则从 <code>APP_JWT_SECRET</code> 派生。</td></tr><tr><td><code>APP_WECHAT_MINI_PROGRAM_APP_ID</code></td><td>HXNI 电气无忧小程序 AppID，多个按相同顺序用英文逗号分隔。</td></tr><tr><td><code>APP_WECHAT_MINI_PROGRAM_APP_SECRET</code></td><td>与上一项一一对应，只能保存在服务端。</td></tr><tr><td><code>BACKEND_PORT</code> / <code>FRONTEND_PORT</code></td><td>宿主机映射端口，默认 8000 / 8080。</td></tr></tbody></table><p>模板见 <code>docs/env/.env.example</code>（Compose 部署）与 <code>docs/env/backend.env.example</code>、<code>docs/env/frontend.env.example</code>（独立部署后端 / 前端时使用）；完整清单（含日志、跨域、限流等）见<a href="/Electrical-Manager/dev-architecture">架构设计</a>。</p><h2 id="运行形态" tabindex="-1">运行形态 <a class="header-anchor" href="#运行形态" aria-label="Permalink to &quot;运行形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>端口</th><th>说明</th></tr></thead><tbody><tr><td>后端</td><td>8000</td><td><code>/health</code>（含 DB 探测）、<code>/api/docs</code>（Swagger）、<code>/api/v1/openapi.json</code>、<code>/api/v1/*</code>、<code>/api/v1/mcp</code></td></tr><tr><td>前端</td><td>容器 80，宿主默认 8080</td><td>Nginx 托管静态资源并代理 <code>/api</code> 到后端</td></tr><tr><td>数据库</td><td>外部 MySQL 8.0</td><td>由部署方用 <code>docs/references/database/init.sql</code> 初始化；容器不自动执行脚本</td></tr><tr><td>持久化</td><td><code>uploads</code>、<code>logs</code> 两个命名卷</td><td>图片、导入临时文件、导出文件与日志</td></tr></tbody></table><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>说明</th></tr></thead><tbody><tr><td>结构与种子数据</td><td><code>docs/references/database/init.sql</code> 是唯一来源，用于新库初始化；<code>server/tests/test_init_sql.py</code> 强制校验它与 ORM 模型一致，改模型必须同步改 <code>init.sql</code>。</td></tr><tr><td>初始账号</td><td><code>admin</code>、<code>warehouse</code>、<code>purchase</code>、<code>hazard</code>、<code>ledger</code>、<code>work</code>、<code>readonly</code>，初始密码均为 <code>123456</code>，首次登录后请修改。</td></tr><tr><td>已有库升级</td><td>仓库不保存增量迁移脚本：先备份，再参照 <code>init.sql</code> 与服务端 ORM 模型的差异，按各自流程改库。</td></tr></tbody></table><p>表结构说明见<a href="/Electrical-Manager/dev-data-model">数据模型</a>。</p><h2 id="前后端分离部署" tabindex="-1">前后端分离部署 <a class="header-anchor" href="#前后端分离部署" aria-label="Permalink to &quot;前后端分离部署&quot;">​</a></h2><p>前端用 Vite 构建，后端与图片地址在<strong>构建阶段</strong>注入并写进静态产物，部署后改服务器环境变量不生效，必须重新构建。</p><h3 id="构建变量" tabindex="-1">构建变量 <a class="header-anchor" href="#构建变量" aria-label="Permalink to &quot;构建变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>必填</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>VITE_API_BASE_URL</code></td><td>分离部署时必填</td><td><code>https://api.example.com</code></td><td>后端地址；只填域名会自动补 <code>/api/v1</code>，也可填完整 API 根地址</td></tr><tr><td><code>VITE_IMAGE_BASE_URL</code></td><td>否</td><td><code>https://img.example.com</code></td><td>图床/CDN；只填域名会自动补 <code>/api/v1/files/images</code>，留空则从后端读</td></tr><tr><td><code>VITE_API_PROXY</code></td><td>否</td><td><code>http://localhost:8000</code></td><td>仅 <code>npm run dev</code> 的本地代理</td></tr><tr><td><code>VITE_BASE_PATH</code></td><td>否</td><td><code>/Electrical-Manager/demo/</code></td><td>部署到子路径时用，默认 <code>/</code></td></tr></tbody></table><p>所有 <code>VITE_*</code> 都会暴露给浏览器，禁止放密钥、Token。地址末尾可带斜杠，构建会自动清理。</p><h3 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>命令</th></tr></thead><tbody><tr><td>Linux</td><td><code>cd web &amp;&amp; npm ci &amp;&amp; VITE_API_BASE_URL=https://api.example.com VITE_IMAGE_BASE_URL=https://img.example.com npm run build</code></td></tr><tr><td>PowerShell</td><td><code>Set-Location web; npm ci; $env:VITE_API_BASE_URL=&#39;https://api.example.com&#39;; $env:VITE_IMAGE_BASE_URL=&#39;https://img.example.com&#39;; npm run build</code></td></tr></tbody></table><p>产物在 <code>web/dist/</code>，CD 阶段把它发布到静态站点、对象存储或 CDN 即可。</p><h3 id="环境划分" tabindex="-1">环境划分 <a class="header-anchor" href="#环境划分" aria-label="Permalink to &quot;环境划分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环境</th><th><code>VITE_API_BASE_URL</code></th><th><code>VITE_IMAGE_BASE_URL</code></th></tr></thead><tbody><tr><td>测试</td><td><code>https://api-test.example.com</code></td><td><code>https://img-test.example.com</code></td></tr><tr><td>生产</td><td><code>https://api.example.com</code></td><td><code>https://img.example.com</code></td></tr></tbody></table><p>每套环境单独出产物，避免同一个静态包跨环境复用。</p><h3 id="后端跨域" tabindex="-1">后端跨域 <a class="header-anchor" href="#后端跨域" aria-label="Permalink to &quot;后端跨域&quot;">​</a></h3><p>后端用 <code>RefererCORSMiddleware</code>：优先按 <code>Referer</code> 解析前端站点，缺失或无效时回退 <code>Origin</code>，并为预检与正常响应（含结构化错误响应）补齐 CORS Header。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Referer: https://spares.example.com/login?redirect=/</span></span>
<span class="line"><span>Origin: https://spares.example.com</span></span>
<span class="line"><span>Access-Control-Allow-Origin: https://spares.example.com</span></span>
<span class="line"><span>Vary: Origin, Referer</span></span></code></pre></div><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>响应头</td><td>暴露 <code>Content-Disposition</code>、<code>X-Request-ID</code> 与性能头 <code>X-Response-Time</code>、<code>X-DB-Time</code>、<code>X-Compute-Time</code>、<code>X-DB-Queries</code></td></tr><tr><td>错误体</td><td>不使用 HTTP 404，错误统一为结构化业务错误体，见<a href="/Electrical-Manager/api-conventions">接口约定</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>配置</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>APP_CORS_ALLOW_CREDENTIALS</code></td><td><code>true</code></td><td>是否允许携带凭证</td></tr><tr><td><code>APP_CORS_MAX_AGE</code></td><td><code>86400</code></td><td>预检结果缓存秒数</td></tr></tbody></table><p>正常部署时 <code>Referer</code> 所属站点应与浏览器 <code>Origin</code> 相同；浏览器不发送 <code>Referer</code> 时自动回退 <code>Origin</code>。</p><h3 id="图片-cdn-图床" tabindex="-1">图片 CDN / 图床 <a class="header-anchor" href="#图片-cdn-图床" aria-label="Permalink to &quot;图片 CDN / 图床&quot;">​</a></h3><p><code>VITE_IMAGE_BASE_URL</code> 只影响图片展示与预览；上传、删除仍走 <code>VITE_API_BASE_URL</code>。</p><table tabindex="0"><thead><tr><th>CDN 规则</th><th>要求</th></tr></thead><tbody><tr><td>代理范围</td><td>仅 <code>GET /api/v1/files/images/*</code>，不要切上传/删除接口</td></tr><tr><td>缓存键</td><td>必须包含 <code>size</code> 查询参数，否则不同尺寸预览互相覆盖</td></tr><tr><td>缓存时间</td><td>遵循后端 <code>Cache-Control</code>；文件 ID 不变则内容不变，适合长缓存</td></tr><tr><td>路径处理</td><td>转发原始路径与查询串，不要重写 <code>file_id</code></td></tr><tr><td>协议</td><td>图床与前端都用 HTTPS</td></tr></tbody></table><p>不用图床时留空 <code>VITE_IMAGE_BASE_URL</code> 即可。</p><h3 id="edgeone-pages" tabindex="-1">EdgeOne Pages <a class="header-anchor" href="#edgeone-pages" aria-label="Permalink to &quot;EdgeOne Pages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>部署配置</td><td><code>web/edgeone.json</code>（EdgeOne 项目根目录为 <code>web/</code>）</td></tr><tr><td>构建产物</td><td><code>dist/</code>（JS/CSS 在 <code>dist/yangrucheng-assets/</code>，文件名带内容 hash）</td></tr><tr><td>缓存规则</td><td><code>/yangrucheng-assets/*</code>、<code>/*.png</code>、<code>/*.jpg</code> → <code>max-age=1209600</code>（14 天）</td></tr></tbody></table><p>图片（<code>logo.png</code>、<code>qrcode.png</code>）在 <code>dist/</code> 根目录，因此 png/jpg 规则用全站后缀匹配而非限定在 <code>yangrucheng-assets/</code> 内；<code>edgeone.json</code> 的 <code>source</code> 是 URL 通配符（以 <code>/</code> 开头、最多一个 <code>*</code>）。</p><h2 id="文档站点" tabindex="-1">文档站点 <a class="header-anchor" href="#文档站点" aria-label="Permalink to &quot;文档站点&quot;">​</a></h2><p>本站由 <code>docs/websites/</code> 下的 VitePress 工程构建：CI 在 <code>main</code> 变更时构建并推送到 <code>gh-pages</code> 分支，由 GitHub Pages 发布。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/websites</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 本地预览</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 产物在 .vitepress/dist</span></span></code></pre></div>`,44)])])}const g=e(i,[["render",o]]);export{k as __pageData,g as default};
